// 允许：实现接口、静态字段、静态方法、额外方法
public record Money(BigDecimal amount, String currency) implements Comparable<Money> {
    public static final Money ZERO = new Money(BigDecimal.ZERO, "CNY");   // 静态字段可以

    public Money {                                                          // 紧凑构造器
        Objects.requireNonNull(amount);
        Objects.requireNonNull(currency);
    }

    public Money plus(Money other) {                                        // 额外方法可以
        if (!currency.equals(other.currency)) {
            throw new IllegalArgumentException("币种不同不能相加");
        }
        return new Money(amount.add(other.amount), currency);               // 复制并修改
    }

    @Override public int compareTo(Money o) { return amount.compareTo(o.amount); }
}

